text:
{
  "title": "استمارة طلب توظيف وإقرار معالجة البيانات الشخصية",
  "planted": [
    {
      "slot": "p1",
      "text": "نظراً لطبيعة بعض المهام الوظيفية المتقدم لها، قد نقوم بجمع بيانات حساسة تشمل الأصول العرقية أو المعتقدات الدينية أو السجلات الجنائية أو البيانات البيومترية والجينية والصحية لتقييم مدى ملاءمتك للعمل، مع قصر الاطلاع على هذه البيانات الطبية والحساسة حصراً على الجهات المعنية بالتقييم الداخلي دون استخدامها لأغراض التسويق المباشر."
    },
    {
      "slot": "p2",
      "text": "يتم جمع البيانات الشخصية من خلال هذه الاستمارة بالحد الأدنى الذي تقتضيه أغراض التوظيف والمفاضلة المهنية بين المتقدمين، مع التركيز على المعلومات الضرورية لإتمام المقابلات الشخصية وتقييم الكفاءة والخبرات السابقة بدقة."
    },
    {
      "slot": "p3",
      "text": "يوافق المتقدم على معالجة بياناته الشخصية المذكورة في هذا الطلب للأغراض المهنية ذات الصلة، ويحق للشركة تعديل أو تغيير آليات المعالجة أو نطاق الاستخدام وفقاً لما تقتضيه مصلحة العمل ومتطلبات الإدارة الداخلية."
    }
  ],
  "neutral": [
    "تخضع هذه الاستمارة وتعاملات التوظيف اللاحقة لأنظمة المملكة العربية السعودية، وتختص الجهات القضائية ذات الصلة بالفصل في أي نزاع قد ينشأ عنها.",
    "تقر بأن جميع المعلومات والبيانات والشهادات المهنية المقدمة من طرفك صحيحة ودقيقة، وتتحمل وحدك المسؤولية القانونية الكاملة عن أي بيانات مضللة أو غير صحيحة.",
    "لا تتقاضى الشركة أي رسوم مالية أو مبالغ نقدية من المتقدمين نظير تقديم طلبات التوظيف أو دراستها أو إجراء المقابلات الشخصية.",
    "يعتبر هذا الطلب مجرد مرحلة أولية لتقييم الكفاءة ولا يمثل عقداً ملزماً للتوظيف إلا بعد توقيع العقد الرسمي المعتمد من الموارد البشرية.",
    "تُقصد بالشركة في هذا المستند شركة الأفق المتقدم للخدمات المهنية، ويُقصد بالمتقدم كل شخص قام بتعبئة هذه الاستمارة بغرض الحصول على وظيفة شاغرة.",
    "تحتفظ الشركة بكافة حقوق الملكية الفكرية والعلمية لجميع الاختبارات التقييمية والنماذج والمواد التدريبية المقدمة للمتقدم خلال مراحل الاختيار."
  ]
}
